import {story} from './story.js';
import {judge} from './judge.js';
import {sfx,setMusic,setMuted as muteSound} from './sound.js';
import {lang,t,tf,localize} from './i18n.js';
import {images,loadArt,drawViews,renderDoll,drawItem,drawCosmetic,drawHair,exportLook,lips,hairs} from './art.js';
const $=s=>document.querySelector(s),clone=o=>structuredClone(o);
const initial={outfit:0,lip:4,blush:35,liner:2,hair:0,shoes:0,accessory:0,hairstyle:0,earrings:-1,bracelet:-1,pose:0,expression:0};
let jewelryCategory='accessories',styleFilter='all';
// Two characters: `state` is whoever is being styled, `other` is the Nana waiting behind her.
const hachiInitial={...initial,face:1,outfit:6,lip:1,blush:45,liner:0,hair:1,hairstyle:1,accessory:2,earrings:2,expression:3};
let who='nana',other=clone(hachiInitial);const names={nana:'Nana',hachi:'Hachi'};
function swapCharacter(){[state,other]=[other,state];who=who==='nana'?'hachi':'nana';history=[];future=[];render();persist();toast(tf('Now styling {0}.',t(names[who])));say(who+'-hello');}
let state=clone(initial),history=[],category='clothes',challenge=0,looks=[],ready=false,toastTimer;
const outfits=[['Leather jacket','Rebel at heart'],['Lace blouse','Soft strength'],['Rose cardigan','A warmer you'],['Plaid skirt','Classic chaos'],['Wide-leg jeans','Everyday mood'],['Slip dress','For later'],['Pink ribbon dress','Sweet as a daydream'],['Floral skirt','Garden romance'],['Lavender cardigan','Soft little moments']];
const shoes=[['Black leather','The original'],['Cherry leather','A darker romance'],['Ivory leather','A softer edge']];
const accessories=[['Silver chains','A little starlight'],['Velvet choker','Heart on a string'],['Pearl necklace','Quietly classic'],['Ruby heart','A little romance'],['Gold layers','Golden hour'],['Safety pin','Punk keepsake']];
const hairstyles=['Tousled bob','Long waves','High ponytail','Twin braids'];
const earrings=[['Silver hoops','Everyday shine'],['Star drops','After-dark sparkle'],['Pearl drops','Quiet romance']];
const bracelets=[['Silver bracelet','A little charm'],['Leather cuff','A tougher edge'],['Pearl bracelet','Softly classic']];
const challenges=[{name:'Snow on the train',brief:'Nana Osaki leaves for Tokyo: punk layers, berry lips, silver and a sharp wing.',checks:[['Choose the leather jacket or plaid skirt',s=>[0,3].includes(s.outfit)],['Wear berry lipstick',s=>s.lip===4],['Add silver chains or a velvet choker',s=>[0,1].includes(s.accessory)],['Finish with winged eyeliner',s=>s.liner===2]]},{name:'Apartment 707',brief:'Hachi meets the landlord: soft textures, a natural lip and a little warmth.',checks:[['Choose a soft or romantic outfit',s=>[1,2,6,7,8].includes(s.outfit)],['Wear nude or rose lipstick',s=>s.lip<2],['Keep eyeliner bare or soft',s=>s.liner<2],['Add a little blush (20–60%)',s=>s.blush>=20&&s.blush<=60]]},{name:'Trapnest after dark',brief:'Nana sees Ren again: an evening silhouette, a bold lip and something that catches the light.',checks:[['Choose the slip dress',s=>s.outfit===5],['Wear brick or berry lipstick',s=>s.lip>=3],['Add silver chains or pearls',s=>[0,2].includes(s.accessory)],['Finish with black boots',s=>s.shoes===0]]},{name:'Blast plays live',brief:'Nana takes the stage: tough layers, hair up and something pinned on.',checks:[['Choose the leather jacket, plaid skirt or wide-leg jeans',s=>[0,3,4].includes(s.outfit)],['Tie up a high ponytail',s=>s.hairstyle===2],['Pin on the safety pin or wear the leather cuff',s=>s.accessory===5||s.bracelet===1],['Strike the hand-on-hip pose',s=>s.pose===1]]},{name:'Hachi’s date',brief:'Something soft, pearls, long waves and a smile. Nervous in the nicest way.',checks:[['Choose the rose cardigan or a romantic dress',s=>[2,6,7,8].includes(s.outfit)],['Let down long waves',s=>s.hairstyle===1],['Wear pearls somewhere',s=>s.accessory===2||s.earrings===2||s.bracelet===2],['Finish with a smile',s=>s.expression===3]]}];
const startChapter=i=>{if(story[i][4]!==who)swapCharacter();challenge=story[i][0];lastStars=-1;persist();render();$('#modal').close();cutscene(i);};
// Voice: prerecorded lines in voice/<lang>/<key>.m4a (generated by scripts/make-voices.mjs). One line plays at a time.
let muted=false,musicOn=false,voice;try{muted=localStorage.getItem('after-school-muted')==='1';musicOn=localStorage.getItem('after-school-music')==='1';}catch{}
function setMusicOn(on){musicOn=on;try{localStorage.setItem('after-school-music',on?'1':'0');}catch{}setMusic(on);$('#music').setAttribute('aria-pressed',on);$('#music').setAttribute('aria-label',t(on?'Music on':'Music off'));}
function say(key){voice?.pause();if(muted)return null;voice=new Audio(`voice/${lang}/${key}.m4a`);voice.play().catch(()=>{});return voice;}
function setMuted(m){muted=m;if(m)voice?.pause();muteSound(m);if(!m&&musicOn)setMusic(true);try{localStorage.setItem('after-school-muted',m?'1':'0');}catch{}$('#sound').textContent=m?'🔇':'🔊';$('#sound').setAttribute('aria-label',t(m?'Sound off':'Sound on'));$('#sound').setAttribute('aria-pressed',!m);}
// Cutscene: both Nanas on the dressing-room set, a slow push-in, the chapter title and narrated subtitles.
function cutscene(i){const [,title,intro]=story[i],el=$('#cutscene');for(const [id,s] of [['#cut-lead',state],['#cut-back',other]]){const c=$(id).getContext('2d');c.clearRect(0,0,300,900);c.drawImage(renderDoll(s),0,0);}
$('#cut-title').textContent=t(title);$('#cut-text').textContent=t(intro);el.hidden=false;el.classList.remove('play');void el.offsetWidth;el.classList.add('play');$('#cut-skip').focus();
let timer;const end=()=>{clearTimeout(timer);voice?.pause();el.hidden=true;toast(t(title));};$('#cut-skip').onclick=end;
const a=say(`ch${i+1}-intro`);timer=setTimeout(end,14000);if(a)a.onended=()=>{clearTimeout(timer);timer=setTimeout(end,1200);};}
// Record your look: draws the stage onto a 9:16 canvas for six seconds with her voice line, then downloads it.
async function recordLook(){if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){toast(t('Video recording is not supported in this browser.'));return;}
const type=['video/mp4','video/webm;codecs=vp9,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));const c=document.createElement('canvas');c.width=720;c.height=1280;const g=c.getContext('2d'),stream=c.captureStream(30);
let ac;if(!muted)try{ac=new AudioContext();const el=new Audio(`voice/${lang}/${who}-hello.m4a`),dest=ac.createMediaStreamDestination(),src=ac.createMediaElementSource(el);src.connect(dest);src.connect(ac.destination);stream.addTrack(dest.stream.getAudioTracks()[0]);setTimeout(()=>el.play().catch(()=>{}),400);}catch{}
const rec=new MediaRecorder(stream,type?{mimeType:type}:{}),chunks=[];rec.ondataavailable=e=>chunks.push(e.data);const btn=$('#record-look');if(btn){btn.disabled=true;btn.textContent=t('Recording…');}
const bg=images['dressing-room'],start=performance.now();rec.start();
await new Promise(done=>{const frame=now=>{const s=(now-start)/1000,z=1.06+.04*s/6,bw=1280*bg.width/bg.height*z;g.drawImage(bg,(720-bw)/2,(1280-1280*z)/2,bw,1280*z);
for(const [cv,x,k] of [[$('#partner'),250,.86],[$('#character'),430,1]]){g.save();g.translate(x,1190);g.rotate(.006*Math.sin(s*.9+k));g.scale(k,k*(1+.008*Math.sin(s*1.9)));g.drawImage(cv,-180,-1080,360,1080);g.restore();}
g.fillStyle='#f3ecdc';g.fillRect(0,1196,720,84);g.fillStyle='#29241f';g.font='38px Georgia';g.textAlign='center';g.fillText('AFTER SCHOOL',360,1250);
if(s<6)requestAnimationFrame(frame);else{rec.onstop=done;rec.stop();}};requestAnimationFrame(frame);});
ac?.close();const blob=new Blob(chunks,{type:rec.mimeType}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='after-school-look.'+(rec.mimeType.includes('mp4')?'mp4':'webm');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);
if(btn){btn.disabled=false;btn.textContent=t('Record video');}toast(t('Video saved.'));}
function showStory(){open('<h2 class="dialog-title">Two Nanas, one Tokyo.</h2><p class="dialog-intro">A story inspired by NANA. Style both Nanas through five chapters; four stars on each scene turns the page.</p><ol class="story-list"></ol>');story.forEach(([ch,title,intro,outro],i)=>{const unlocked=i===0||done.includes(story[i-1][0]),complete=done.includes(ch),li=document.createElement('li');li.className='story-card'+(complete?' done':unlocked?'':' locked');li.innerHTML=`<h3>${title}</h3><p>${unlocked?intro:'Finish the chapter before to read on.'}</p>${complete?`<p class="story-outro">${outro}</p>`:''}`;if(unlocked&&!complete){const b=document.createElement('button');b.className='dialog-button';b.textContent=tf('Style {0} for this scene',t(names[story[i][4]]));b.onclick=()=>startChapter(i);li.append(b);}$('.story-list').append(li);});}
function chapterEnd(i){const next=story[i+1];open(`<h2 class="dialog-title">${story[i][1]}</h2><p class="story-outro">${story[i][3]}</p>${next?'<button class="dialog-button" id="next-chapter">'+tf('Next: {0}',t(next[1]))+'</button>':'<p class="dialog-intro">To be continued, in room 707.</p>'}`);if(next)$('#next-chapter').onclick=()=>startChapter(i+1);say(`ch${i+1}-outro`);}
const stars=s=>challenges[challenge].checks.filter(([,fn])=>fn(s)).length;let done=[],lastStars=-1,future=[],streak={days:0,last:-1};const today=()=>Math.floor(Date.now()/864e5),daily=today()%challenges.length;
function award(n){if(n===4&&!done.includes(challenge)){done.push(challenge);const t=today();if(streak.last!==t)streak={days:streak.last===t-1?streak.days+1:1,last:t};persist();sfx('complete');toast(tf('Brief complete! {0} earned four stars.',t(challenges[challenge].name))+(streak.days>1?tf(' {0}-day streak.',streak.days):''));say(who+'-win');$('#done-count').textContent=`(${done.length}/${challenges.length})`;const i=story.findIndex(c=>c[0]===challenge);if(i>=0)setTimeout(()=>chapterEnd(i),1800);}}
function valid(s){return s&&['outfit','lip','blush','liner','hair','shoes','accessory'].every(k=>Number.isInteger(s[k]))&&s.outfit>=0&&s.outfit<9&&s.lip>=0&&s.lip<5&&s.blush>=0&&s.blush<=100&&s.liner>=0&&s.liner<3&&s.hair>=0&&s.hair<4&&s.shoes>=0&&s.shoes<3&&s.accessory>=-1&&s.accessory<6&&(s.hairstyle===undefined||(Number.isInteger(s.hairstyle)&&s.hairstyle>=0&&s.hairstyle<4))&&(s.pose===undefined||(Number.isInteger(s.pose)&&s.pose>=0&&s.pose<3))&&(s.expression===undefined||(Number.isInteger(s.expression)&&s.expression>=0&&s.expression<4))&&['earrings','bracelet'].every(k=>s[k]===undefined||(Number.isInteger(s[k])&&s[k]>=-1&&s[k]<3));}
const migrate=s=>({...initial,...s});
try{const data=JSON.parse(localStorage.getItem('after-school-v1')||'null');if(valid(data?.state))state=migrate(data.state);if(valid(data?.other))other=migrate(data.other);if(data?.who==='hachi')who='hachi';if(Array.isArray(data?.looks))looks=data.looks.filter(l=>valid(l.state)&&typeof l.name==='string').slice(0,12).map(l=>({...l,state:migrate(l.state)}));if(Number.isInteger(data?.challenge)&&data.challenge>=0&&data.challenge<challenges.length)challenge=data.challenge;if(data?.challenge===undefined)challenge=daily;if(Number.isInteger(data?.streak?.days)&&Number.isInteger(data?.streak?.last))streak=data.streak;if(Array.isArray(data?.done))done=data.done.filter(i=>Number.isInteger(i)&&i>=0&&i<challenges.length);}catch{}
// Shared look: #<base64 json> in the URL loads that look, then the hash is cleared.
try{const h=JSON.parse(atob(location.hash.slice(1)));if(valid(h)){state=migrate(h);window.history.replaceState(null,'',location.pathname);setTimeout(()=>toast('Shared look loaded.'),300);}}catch{}
state.face=who==='hachi'?1:0;other.face=1-state.face;
function persist(){try{localStorage.setItem('after-school-v1',JSON.stringify({state,other,who,looks,challenge,done,streak}));return true;}catch{toast('Browser storage is unavailable. You can still download your look.');return false;}}
function toast(text){$('#toast').textContent=t(text);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function change(patch){future.length=0;history.push(clone(state));if(history.length>60)history.shift();Object.assign(state,patch);state.face=who==='hachi'?1:0;render();persist();sfx('tap');if(!calm.matches&&['outfit','pose','hairstyle'].some(k=>k in patch))$('#character').animate([{scale:.965,opacity:.55,filter:'drop-shadow(5px 8px 7px #0004) brightness(1.15)'},{scale:1,opacity:1}],{duration:420,easing:'cubic-bezier(.2,.9,.25,1.15)'});}
// Idle life: breathing head bob, slight sway and blinks. Saved looks and exports stay still.
const calm=matchMedia('(prefers-reduced-motion: reduce)');let nextBlink=2500;
function idle(t){requestAnimationFrame(idle);if(!ready||calm.matches||document.hidden)return;const s=t/1000;if(t>nextBlink+150)nextBlink=t+2200+Math.random()*3500;const blink=t>nextBlink&&state.expression<2;drawViews(state,{headY:-.9-.9*Math.sin(s*1.9),tilt:.014*Math.sin(s*.75),faceFrame:blink?2:undefined});}
requestAnimationFrame(idle);
function swatches(){$('#hairstyle-options').replaceChildren(...hairstyles.map((name,i)=>{const b=document.createElement('button');b.className='hairstyle';b.setAttribute('aria-label',name);b.setAttribute('aria-pressed',state.hairstyle===i);const art=document.createElement('canvas');drawHair(art,state,i);art.setAttribute('aria-hidden','true');b.append(art,document.createTextNode(name));b.onclick=()=>change({hairstyle:i});return b;}));const lipNames=['Nude','Rose','Mauve','Brick','Berry'];$('#lip-swatches').replaceChildren(...lips.map((color,i)=>{const b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',color);b.title=lipNames[i];b.setAttribute('aria-label',tf('{0} lipstick',t(lipNames[i])));b.setAttribute('aria-pressed',state.lip===i);const art=document.createElement('canvas');drawCosmetic(art,state,'lip',i);art.setAttribute('aria-hidden','true');b.append(art);b.onclick=()=>change({lip:i});return b;}));$('#hair-swatches').replaceChildren(...hairs.map((color,i)=>{const b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',color);b.setAttribute('aria-label',['Ink black hair','Chestnut hair','Cherry hair','Honey hair'][i]);b.setAttribute('aria-pressed',state.hair===i);b.title=b.getAttribute('aria-label');b.innerHTML='<span class="hair"></span>';b.onclick=()=>change({hair:i});return b;}));$('#liner-options').replaceChildren(...['Bare','Soft','Winged'].map((name,i)=>{const b=document.createElement('button');b.className='liner';b.setAttribute('aria-pressed',state.liner===i);b.setAttribute('aria-label',tf('{0} eyeliner',t(name)));const art=document.createElement('canvas');drawCosmetic(art,state,'liner',i);art.setAttribute('aria-hidden','true');b.append(art,document.createTextNode(name));b.onclick=()=>change({liner:i});return b;}));}
function inventory(){
const jewelry=category==='accessories';
$('#jewelry-tabs').hidden=!jewelry;$('#style-filters').hidden=category!=='clothes';
const kind=jewelry?jewelryCategory:category;
const entries=kind==='clothes'?outfits:kind==='shoes'?shoes:kind==='earrings'?[...earrings,['No earrings','Keep it simple']]:kind==='bracelets'?[...bracelets,['No bracelet','Keep it simple']]:[...accessories,['No necklace','Let the outfit speak']];
$('#inventory').classList.toggle('fresh',inventory.last!==(inventory.last=kind+styleFilter));
const key=kind==='clothes'?'outfit':kind==='shoes'?'shoes':kind==='earrings'?'earrings':kind==='bracelets'?'bracelet':'accessory';
$('#inventory').replaceChildren(...entries.map(([title,subtitle],i)=>{const index=jewelry&&i===entries.length-1?-1:i;if(kind==='clothes'&&((styleFilter==='punk'&&!([0,3,4,5].includes(index)))||(styleFilter==='romantic'&&!([1,2,6,7,8].includes(index)))))return null;const b=document.createElement('button');b.className='item'+(state[key]===index?' selected':'');b.setAttribute('aria-pressed',state[key]===index);b.setAttribute('aria-label',title);const canvas=document.createElement('canvas');canvas.setAttribute('aria-hidden','true');drawItem(canvas,kind,index,state);const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=subtitle;b.append(canvas,strong,small);b.onclick=()=>change({[key]:index});return b;}).filter(Boolean));
$('#inventory-note').textContent=category==='clothes'?'Choose a complete outfit, then make it yours.':category==='shoes'?(state.outfit>=6?'Romantic outfits include matching Mary Janes or ballet flats. Boot finishes apply to punk outfits.':'Your platform boots, in three finishes.'):'Mix a necklace, earrings and a bracelet.';
}

function render(){if(!ready)return;drawViews(state);const partner=$('#partner').getContext('2d');partner.clearRect(0,0,600,1800);partner.drawImage(renderDoll(other),0,0,600,1800);$('#partner').title=tf('Switch to {0}',t(names[who==='nana'?'hachi':'nana']));document.querySelectorAll('[data-who]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.who===who));document.querySelectorAll('[data-pose]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.pose)===state.pose));document.querySelectorAll('[data-expression]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.expression)===state.expression));swatches();inventory();$('#blush').value=state.blush;$('#blush-value').value=state.blush+'%';$('#undo').disabled=history.length===0;$('#redo').disabled=future.length===0;$('#saved-count').textContent=looks.length?`(${looks.length})`:'';$('#challenge-title').textContent=challenges[challenge].name;const n=stars(state);$('#challenge-progress').textContent='★'.repeat(n)+'☆'.repeat(4-n);$('#challenge-progress').title=tf('{0} of 4 details match the brief',n);if(n>lastStars&&lastStars>=0&&!calm.matches){$('#challenge-progress').animate([{scale:1.25,color:'#b8324f'},{scale:1}],{duration:400});if(n<4)sfx('star');}if(lastStars>=0)award(n);lastStars=n;$('#done-count').textContent=done.length?`(${done.length}/${challenges.length})`:'';}
function open(content){$('#modal-body').replaceChildren();if(typeof content==='string')$('#modal-body').innerHTML=content;else $('#modal-body').append(content);if(!$('#modal').open)$('#modal').showModal();}
function showChallenges(){open(`<h2 class="dialog-title">A look for every story.</h2><p class="dialog-intro">Choose a brief, dress your character, then check your look. Each match earns one star. Free styling is always welcome.${streak.days>1&&streak.last>=today()-1?` <strong>${tf('{0}-day streak.',streak.days)}</strong>`:''}</p><div class="challenge-list"></div>`);challenges.forEach((ch,i)=>{const b=document.createElement('button');b.className='challenge-card'+(i===challenge?' selected':'')+(done.includes(i)?' done':'');b.innerHTML=`<h3>${ch.name}</h3><p>${ch.brief}</p><span>${done.includes(i)?'★ Completed':i===challenge?'Current brief':'Style this story →'}</span>${i===daily?'<em class="today">Today’s brief</em>':''}`;b.onclick=()=>{challenge=i;lastStars=-1;persist();render();$('#modal').close();toast(tf('New brief: {0}',t(ch.name)));};$('.challenge-list').append(b);});}
function checkLook(){const ch=challenges[challenge],score=stars(state),j=judge(state);award(score);open(`<h2 class="dialog-title">${ch.name}</h2><div class="score">${'★'.repeat(score)}${'☆'.repeat(4-score)}</div><aside class="judge"><strong>${tf('Style judge: {0}/100',j.score)}</strong><ul>${j.notes.map(n=>`<li class="${n.good?'good':'tip'}">${t(n.text)}</li>`).join('')}</ul></aside><p class="dialog-intro">${score===4?'You nailed the brief. Save this one.':'Your look, your rules. These details bring it closer to the brief.'}</p><ul class="score-details">${ch.checks.map(([label,fn])=>`<li>${fn(state)?'✓':'○'} ${label}</li>`).join('')}</ul><button class="dialog-button" id="back-style">${score===4?'Save this look':'Keep styling'}</button>`);$('#back-style').onclick=()=>score===4?saveDialog():$('#modal').close();}
function saveDialog(){if(looks.length>=12){toast('Your album has 12 looks. Remove one to make room.');showSaved();return;}open('<h2 class="dialog-title">Keep this feeling.</h2><p class="dialog-intro">Save this look to your browser album. Download a portrait to keep a copy anywhere.</p><img class="save-preview" alt="Preview of your current look"><form id="save-form"><label class="name-field">Look name<input id="look-name" maxlength="40" required autocomplete="off"></label><button class="dialog-button" type="submit">Add to my album</button> <button class="dialog-button secondary" type="button" id="share-look">Copy share link</button> <button class="dialog-button secondary" type="button" id="record-look">Record video</button></form>');$('#share-look').onclick=()=>share(state);$('#record-look').onclick=recordLook;$('.save-preview').src=exportLook(state).toDataURL('image/jpeg',.8);$('#look-name').value=t(challenges[challenge].name);$('#save-form').onsubmit=e=>{e.preventDefault();const name=$('#look-name').value.trim();if(!name){$('#look-name').focus();return;}looks.unshift({id:crypto.randomUUID(),name,state:clone(state)});sfx('save');const ok=persist();render();$('#modal').close();toast(ok?'Look saved to your album.':'Saved for this visit. Download it to keep a copy.');};}
const share=s=>navigator.clipboard.writeText(location.origin+location.pathname+'#'+btoa(JSON.stringify(s))).then(()=>toast('Share link copied.'),()=>toast('Could not copy. Try a newer browser.'));
function download(s){const a=document.createElement('a');a.download='after-school-look.png';a.href=exportLook(s).toDataURL('image/png');a.click();}
function showSaved(){open('<h2 class="dialog-title">Your little lookbook.</h2><p class="dialog-intro">Saved on this browser. Restore a look to keep styling, or download it as a portrait.</p><div class="saved-grid"></div>');if(!looks.length){$('.saved-grid').innerHTML='<p class="empty">Your next favorite look belongs here.</p>';return;}looks.forEach(l=>{const card=document.createElement('article');card.className='saved-card';const img=document.createElement('img');img.src=exportLook(l.state).toDataURL('image/jpeg',.65);img.alt=l.name;const h=document.createElement('h3');h.textContent=l.name;const actions=document.createElement('div');actions.className='saved-actions';for(const [label,fn]of [['Wear',()=>{change(clone(l.state));$('#modal').close();toast('Look restored.');}],['Download',()=>download(l.state)],['Share',()=>share(l.state)],['Remove',()=>{looks=looks.filter(x=>x.id!==l.id);persist();render();showSaved();}]]){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label',label+' '+l.name);b.onclick=fn;actions.append(b);}card.append(img,h,actions);$('.saved-grid').append(card);});}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#story').onclick=showStory;$('#challenges').onclick=showChallenges;$('#challenge-title').onclick=showChallenges;$('#check-look').onclick=checkLook;$('#saved').onclick=showSaved;$('#studio').onclick=()=>{$('#modal').close();window.scrollTo({top:0,behavior:'smooth'});};$('#help').onclick=()=>open('<h2 class="dialog-title">Your studio. Your rules.</h2><ol class="help-copy"><li>Pick one of nine complete outfits from the wardrobe.</li><li>Try lipstick, blush and eyeliner in the vanity. Switch to Hair for hairstyles and color.</li><li>Mix necklaces, earrings and bracelets. Punk outfits offer boot finishes; romantic outfits have matching shoes.</li><li>Choose a pose and facial expression for the finished portrait.</li><li>Switch between Nana and Hachi at the top of the stage, or tap the one standing behind. Each keeps her own look.</li><li>Open Story for a five-chapter tale inspired by NANA. Each chapter is a scene; four stars turns the page.</li><li>Or follow any challenge brief. The stars on the stage note update as you style; four stars completes the brief.</li><li>Save your favorites, then open Saved looks to wear or download them.</li><li>Use Record video in the save dialog to keep a short clip with her voice.</li></ol><p class="dialog-intro">No account needed to play. Your album stays in this browser. Clearing browser storage removes saved looks.</p>');
for(const tab of ['makeup','hair'])$('#'+tab+'-tab').onclick=()=>{for(const t of ['makeup','hair']){$('#'+t+'-tab').setAttribute('aria-selected',t===tab);$('#'+t+'-panel').hidden=t!==tab;}};
$('#wardrobe-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$('#wardrobe-tabs').querySelectorAll('button').forEach(t=>t.setAttribute('aria-selected',t===b));inventory();});
$('#jewelry-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-jewelry]');if(!b)return;jewelryCategory=b.dataset.jewelry;$('#jewelry-tabs').querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',t===b));inventory();});
let blushBefore=null;$('#blush').addEventListener('input',()=>{if(!blushBefore)blushBefore=clone(state);state.blush=Number($('#blush').value);drawViews(state);$('#blush-value').value=state.blush+'%';});$('#blush').addEventListener('change',()=>{if(blushBefore){history.push(blushBefore);blushBefore=null;}render();persist();});$('#undo').onclick=()=>{if(history.length){future.push(clone(state));state=history.pop();render();persist();}};$('#redo').onclick=()=>{if(future.length){history.push(clone(state));state=future.pop();render();persist();}};$('#random').onclick=()=>change({outfit:Math.floor(Math.random()*9),lip:Math.floor(Math.random()*5),blush:Math.floor(Math.random()*71),liner:Math.floor(Math.random()*3),hair:Math.floor(Math.random()*4),shoes:Math.floor(Math.random()*3),accessory:Math.floor(Math.random()*7)-1,hairstyle:Math.floor(Math.random()*4),earrings:Math.floor(Math.random()*4)-1,bracelet:Math.floor(Math.random()*4)-1,pose:Math.floor(Math.random()*3),expression:Math.floor(Math.random()*4)});$('#save').onclick=saveDialog;
window.render_game_to_text=()=>JSON.stringify({ready,mode:'styling',who,state,other,category,challenge:challenges[challenge].name,stars:stars(state),done,savedLooks:looks.length,undo:history.length,redo:future.length,streak,daily});window.advanceTime=()=>render();
loadArt().then(()=>{ready=true;$('#loading').hidden=true;render();}).catch(error=>{$('#loading').textContent='The artwork could not load. Please refresh to try again.';console.error(error);});

$('#who-controls').addEventListener('click',e=>{const b=e.target.closest('[data-who]');if(b&&b.dataset.who!==who)swapCharacter();});$('#partner').onclick=swapCharacter;
$('#pose-controls').addEventListener('click',e=>{const b=e.target.closest('[data-pose]');if(b)change({pose:Number(b.dataset.pose)});});
$('#expression-controls').addEventListener('click',e=>{const b=e.target.closest('[data-expression]');if(b)change({expression:Number(b.dataset.expression)});});
$('#style-filters').addEventListener('click',e=>{const b=e.target.closest('[data-style]');if(!b)return;styleFilter=b.dataset.style;$('#style-filters').querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',t===b));inventory();});
$('#sound').onclick=()=>setMuted(!muted);setMuted(muted);$('#music').onclick=()=>setMusicOn(!musicOn);$('#music').setAttribute('aria-pressed',musicOn);addEventListener('pointerdown',()=>{if(musicOn)setMusic(true);},{once:true});$('#lang').textContent=lang==='ja'?'EN':'日本語';$('#lang').lang=lang==='ja'?'en':'ja';$('#lang').onclick=()=>{location.search='?lang='+(lang==='ja'?'en':'ja');};
addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#cutscene').hidden){$('#cut-skip').click();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input')){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();}});
